SELECT COUNT(*) FROM users as u, comments as c, postLinks as pl, postHistory as ph, posts as p WHERE pl.RelatedPostId = p.Id AND c.PostId = p.Id AND u.Id= c.UserId AND ph.PostId = p.Id AND u.Reputation>=1 AND u.Reputation<=491 AND u.DownVotes>=0 AND u.DownVotes<=0 AND c.CreationDate>='2010-07-11 12:25:05'::timestamp AND c.CreationDate<='2014-09-11 13:43:09'::timestamp AND pl.LinkTypeId=1 AND ph.CreationDate>='2010-08-06 03:14:53'::timestamp;